{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_wrong_status_code",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.attr_http_response_status_code AS caller_status, c.attr_http_response_status_code AS callee_status, c.attr_span_kind AS callee_kind, count(*) AS n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id WHERE p.service_name = 'ts-travel-plan-service' AND p.attr_span_kind = 'Client' AND p.span_name = 'POST' AND c.service_name = 'ts-route-plan-service' AND c.attr_span_kind = 'Server' GROUP BY 1,2,3",
          "claim": "Travel-plan client POSTs show status 404 while the matching route-plan server spans returned 200, for 753 calls."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) AS n FROM abnormal_logs WHERE service_name = 'ts-travel-plan-service' AND level = 'SEVERE' AND message LIKE '%HttpClientErrorException$NotFound%' GROUP BY 1,2",
          "claim": "Travel-plan logs 753 SEVERE NotFound exceptions from its call to route-plan quickestRoute; normal period has none."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'ts-travel-plan-service' AND attr_span_kind = 'Server' AND span_name LIKE '%quickest%' GROUP BY 1,2,3,4,5",
          "claim": "Travel-plan quickest endpoint returns 500 errors on the server side for the failing requests."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'ts-ui-dashboard' AND attr_span_kind = 'Server' AND span_name LIKE '%travelPlan/quickest%' GROUP BY 1,2,3",
          "claim": "Ui-dashboard quickest-travel-plan server spans return 500 as travel-plan failures propagate to the user-facing tier."
        }
      ]
    },
    {
      "from": "ts-ui-dashboard",
      "to": "loadgenerator",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'loadgenerator' AND span_name LIKE '%travelPlan/quickest%' GROUP BY 1,2,3",
          "claim": "Load-generated user requests to travelPlan/quickest end in Error status, showing the user-visible failure."
        }
      ]
    }
